-- The settler's take statement (src/grind/internal/settlement.gleam, `take`),
-- with its parameters bound to the queue that settlement-take.sh fills.
UPDATE grind_jobs AS job SET settle_at = clock_timestamp() + make_interval(secs => GREATEST(LEAST(30000::float8 * power(2::float8, LEAST(job.settle_tries, 40)::float8), GREATEST(3600000::float8, 30000::float8)), 30000::float8) / 1000.0), settle_tries = job.settle_tries + 1 FROM (SELECT id FROM grind_jobs WHERE queue = 'bench-settle' AND state = 'uncertain' AND settle_at IS NOT NULL AND settle_attempt_id = attempt_id AND settle_at <= statement_timestamp() AND (worker_id, worker_version) IN (SELECT * FROM unnest(ARRAY['bench.settle']::text[], ARRAY['v1']::text[])) AND NOT (id = ANY(ARRAY[]::bigint[])) ORDER BY settle_at, id FOR NO KEY UPDATE SKIP LOCKED LIMIT 1) AS candidate WHERE job.id = candidate.id RETURNING job.id;
